import six
import glob
import os
import re
from abc import ABCMeta, abstractmethod


@six.add_metaclass(ABCMeta)
class LogsReader(object):
    """Top-level base class for log readers handling multiple files.

    """

    def __init__(self, file_obj_iterator, timezone="utc", **kwargs):
        """Initialize a log reader

        :param [list[file]] file_obj_iterator: iterable of file objects

        An iterator is an object that contains a countable number of values.
        An iterator is an object that can be iterated upon, meaning that you can traverse through all the values.
        Technically, in Python, an iterator is an object which implements the iterator protocol,
        which consist of the methods __iter__() and __next__().

        """
        super(LogsReader, self).__init__(**kwargs)
        self._file_obj_iterator = file_obj_iterator
        self._timezone = timezone

    @staticmethod
    def _open(file_name):
        return open(file_name, "rb")

    @staticmethod
    def _get_file_paths(dir_path, file_pattern):
        return glob.glob(os.path.join(
            dir_path,
            file_pattern))

    @classmethod
    def from_dir(cls, dir_path, file_pattern, **kwargs):
        """
        Create a logs reader from a directory path and file pattern.

        :param str dir_path: directory path
        :param str file_pattern: file pattern ex:"*_PM_*"

        :return: a LogsReader
        """
        return cls(
            file_obj_iterator=(
                cls._open(file_name)
                for file_name in cls._get_file_paths(
                    re.sub(r"[\[|\]]", r"[\g<0>]", dir_path),
                    file_pattern)),
            **kwargs)

    @abstractmethod
    def __iter__(self):
        """Yields the next log entry."""
